CREATE DATABASE Customer_shopping_behavior;

USE customer_shopping_behavior;

-- RENAME TABLE customer_data TO customer;

SELECT * from customer_data
LIMIT 10;


-- Q1. What is the total revenue generated by male vs. female customers?
SELECT Gender, SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY gender;

-- Q2. Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id, purchase_amount
FROM customer
WHERE discount_applied = 'Yes' AND purchase_amount >= (SELECT AVG(purchase_amount) FROM customer);

-- Q3. Which are the top 5 products with the highest average review rating?
SELECT item_purchased AS Product, ROUND(AVG(Review_rating), 2) AS avg_rating
FROM customer
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC
LIMIT 5;
  
-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
SELECT shipping_type, ROUND(AVG(purchase_amount),2) AS 'AVG Purchase Amount'
FROM customer
WHERE shipping_type IN ('Standard','Express')
GROUP BY shipping_type; 

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.
SELECT subscription_status,
COUNT(subscription_status) AS Total_customers,
ROUND(AVG(Purchase_amount), 2) Avg_spent,
SUM(Purchase_amount) total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue, avg_spent DESC;

-- Alternative approach: 
SELECT (CASE
	WHEN subscription_status = 'Yes' THEN 'Subscribers'
    ELSE 'Non-Subscribers'
    END) AS category,
AVG(Purchase_amount) AS Avg_spent,
SUM(Purchase_amount) AS Total_spent
FROM customer
GROUP BY subscription_status;

-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?
SELECT item_purchased AS product, 
ROUND(100* SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/COUNT(*), 2) AS Discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY Discount_rate DESC
LIMIT 5;

-- Alternate Query
SELECT c1.item_purchased AS product, 
ROUND(100* COUNT(c1.item_purchased)/c2.total_items_sold , 2) AS With_discount
FROM customer c1
JOIN (SELECT item_purchased, COUNT(item_purchased) AS total_items_sold 
	FROM customer
    GROUP BY item_purchased) c2
ON c1.item_purchased = c2.item_purchased
WHERE c1.discount_applied = 'Yes'
GROUP BY c1.item_purchased
ORDER BY With_discount DESC
LIMIT 5;
-- Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, 
-- and show the count of each segment.
SELECT 'New' as customer_type, 
SUM(CASE WHEN previous_purchases = 1 THEN 1 ELSE 0 END) AS 'No. of customers'
FROM customer
UNION ALL
SELECT 'Returning' as customer_type, 
SUM(CASE WHEN previous_purchases BETWEEN 2 AND 10 THEN 1 ELSE 0 END) AS 'No. of customers'
FROM customer
UNION ALL
SELECT 'Loyal' as customer_type, 
SUM(CASE WHEN previous_purchases >10 THEN 1 ELSE 0 END) AS 'No. of customers'
FROM customer;

-- Alternate Query
SELECT (CASE 
	WHEN previous_purchases = 1 THEN 'New'
    WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
    ELSE 'Loyal' END) AS Customer_type,
COUNT(*) AS 'No of customers'
FROM customer
GROUP BY customer_type;

-- Method 3: USING CTE
WITH customer_segment AS (
SELECT customer_id, previous_purchases,
CASE WHEN previous_purchases = 1 THEN 'New'
	WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
    ELSE 'Loyal' END AS customer_type
FROM  customer)

SELECT customer_type, COUNT(*) AS 'No of customers'
FROM Customer_segment
GROUP BY customer_type;

-- Q8. What are the top 3 most purchased products within each category?
WITH item_count AS (
SELECT item_purchased, category, 
COUNT(customer_id) AS Total_orders, 
ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
FROM customer
GROUP BY item_purchased, category)

SELECT Item_rank, category, item_purchased, Total_orders
FROM item_count
WHERE item_rank <=3;

-- Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT Subscription_status, COUNT(*) AS Repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

SELECT ROUND(100* SUM(CASE WHEN subscription_status= 'Yes' THEN 1 ELSE 0 END)/ COUNT(customer_id), 2) AS '% of subscribers'
FROM customer 
WHERE previous_purchases>5; 

-- Q10. What is the revenue contribution of each age group?
SELECT age_group, 
SUM(purchase_amount) AS revenue
FROM customer
GROUP BY age_group
ORDER BY revenue DESC;
